head.script:
scwin.ibx_openPopup_onclick = function(e) {
	requires("uiplugin.popup");
	var opts = {
		"id" : "popup_sub1",
		"type" : "wframePopup",
		"width" : "300px",
		"height" : "200px",
		"top" : 100,
		"left" : 100,
		"popupName" : "popup_sub1",
		"modal" : true,
		"useIFrame" : true,
		"title" : "popup_sub1",
		"disableCloseButton" : false,
		"useControl" : true,
		"controls" : { "minimize" : true, "maximize" : true, "close" : true },
		"processMsgFrame" : true,
		"windowDragMove" : true
	};
	$p.openPopup("/sample/common_link/p_popup_openPopup_modal_WESD-982_(WSQ-5324)_sub1.xml", opts);
};

scwin.checkVal = function() {
	return (document.getElementById('_modal') || document.getElementById('mf__modal')).style.display == 'none';
};
